#[derive(Clone, Copy, Debug)]
enum ScrutinyAssociation5Step {
    Start,
    OnInit,
    OnEnable,
    OnTimer7200000,
}

fn scrutiny_association_5_run(ctx: &Ctx, mut step: ScrutinyAssociation5Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            ScrutinyAssociation5Step::Start => {
                step = ScrutinyAssociation5Step::OnInit;
                continue 'machine;
            }
            ScrutinyAssociation5Step::OnInit => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            ScrutinyAssociation5Step::OnEnable => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            ScrutinyAssociation5Step::OnTimer7200000 => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                if (ctx.var("$dts_result").get()? == 0 || ctx.var("$dts_result").get()? == 3) {
                    ctx.call(Function::Announce, vec![Val::from("Currently, the Dungeon Teleport Service Provider Election is being held in all major cities. Your participation is appreciated."), ctx.constant("BC_ALL")?, Val::from("0x70dbdb")])?;
                }
                ctx.call(Function::DoNpcEvent, vec![Val::from("Scrutiny Association#5::OnEnable")])?;
                return Err(Stop::End);
            }
        }
    }
}

