fn scrutiny_association_7_run(ctx: &Ctx, mut step: ScrutinyAssociation7Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            ScrutinyAssociation7Step::Start => {
                step = ScrutinyAssociation7Step::OnEnable;
                continue 'machine;
            }
            ScrutinyAssociation7Step::OnEnable => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            ScrutinyAssociation7Step::OnTimer1000 => {
                ctx.call(
                    Function::Announce,
                    vec![
                        Val::from("All the votes for the Dungeon Teleport Service Provider Election have been received and counted."),
                        ctx.constant("BC_ALL")?,
                        Val::from("0x70dbdb"),
                    ],
                )?;
                return Err(Stop::End);
            }
            ScrutinyAssociation7Step::OnTimer5000 => {
                ctx.call(
                    Function::Announce,
                    vec![
                        Val::from("The results are now in..."),
                        ctx.constant("BC_ALL")?,
                        Val::from("0x70dbdb"),
                    ],
                )?;
                return Err(Stop::End);
            }
            ScrutinyAssociation7Step::OnTimer10000 => {
                ctx.call(
                    Function::Announce,
                    vec![
                        Val::from("This time, Kafra Corporation will be the Dungeon Teleport Service Provider."),
                        ctx.constant("BC_ALL")?,
                        Val::from("0x70dbdb"),
                    ],
                )?;
                return Err(Stop::End);
            }
            ScrutinyAssociation7Step::OnTimer15000 => {
                ctx.call(
                    Function::Announce,
                    vec![
                        Val::from("Many thanks to all of you who have voted and shown your support."),
                        ctx.constant("BC_ALL")?,
                        Val::from("0x70dbdb"),
                    ],
                )?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn scrutiny_association_7(ctx: &Ctx) -> Script {
    scrutiny_association_7_run(ctx, ScrutinyAssociation7Step::Start, Vec::new()).map(|_| ())
}

